import React, { useState, useEffect, useContext } from 'react';
import { AuthContext } from '../../../context/AuthContext';
import axios from 'axios';
import { FaPlus, FaEdit, FaTrash, FaSearch, FaEye, FaEyeSlash } from 'react-icons/fa';
import styles from '../AdminDashboard.module.css';
import { mockServices } from '../../../services/mockServices';

const BlogManagement = () => {
  const { accessToken } = useContext(AuthContext);
  const [blogs, setBlogs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingBlog, setEditingBlog] = useState(null);
  const [formData, setFormData] = useState({
    title: '',
    content: '',
    summary: '',
    category: '',
    image: '',
    tags: [],
    published: true,
    featured: false
  });
  const [filters, setFilters] = useState({
    category: '',
    published: '',
    featured: ''
  });
  const [tagInput, setTagInput] = useState('');

  // Available categories
  const categories = [
    'Deals', 'Savings Tips', 'Shopping Guide', 'Cashback', 'Coupons', 
    'Lifestyle', 'Technology', 'Fashion', 'Travel', 'Food'
  ];

  useEffect(() => {
    fetchBlogs();
  }, [accessToken, currentPage, filters]);

  const fetchBlogs = async () => {
    try {
      setLoading(true);
      
      // Use mock service instead of real API
      const response = await mockServices.getBlogPosts(currentPage, 10);
      
      setBlogs(response.data);
      setTotalPages(response.pagination.totalPages);
      setError(null);
    } catch (err) {
      console.error('Error fetching blogs:', err);
      setError('Failed to load blog posts. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = (e) => {
    e.preventDefault();
    setCurrentPage(1);
    fetchBlogs();
  };

  const handleFilterChange = (e) => {
    const { name, value } = e.target;
    setFilters(prev => ({
      ...prev,
      [name]: value
    }));
    setCurrentPage(1);
  };

  const resetFilters = () => {
    setFilters({
      category: '',
      published: '',
      featured: ''
    });
    setSearchTerm('');
    setCurrentPage(1);
  };

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const handleTagInputChange = (e) => {
    setTagInput(e.target.value);
  };

  const handleTagInputKeyDown = (e) => {
    if (e.key === 'Enter' || e.key === ',') {
      e.preventDefault();
      addTag();
    }
  };

  const addTag = () => {
    const tag = tagInput.trim();
    if (tag && !formData.tags.includes(tag)) {
      setFormData(prev => ({
        ...prev,
        tags: [...prev.tags, tag]
      }));
      setTagInput('');
    }
  };

  const removeTag = (tagToRemove) => {
    setFormData(prev => ({
      ...prev,
      tags: prev.tags.filter(tag => tag !== tagToRemove)
    }));
  };

  const openAddModal = () => {
    setEditingBlog(null);
    setFormData({
      title: '',
      content: '',
      summary: '',
      category: '',
      image: '',
      tags: [],
      published: true,
      featured: false
    });
    setTagInput('');
    setIsModalOpen(true);
  };

  const openEditModal = (blog) => {
    setEditingBlog(blog);
    setFormData({
      title: blog.title || '',
      content: blog.content || '',
      summary: blog.summary || '',
      category: blog.category || '',
      image: blog.image || '',
      tags: blog.tags || [],
      published: blog.published !== undefined ? blog.published : true,
      featured: blog.featured || false
    });
    setTagInput('');
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingBlog(null);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    try {
      setLoading(true);
      
      if (editingBlog) {
        // Update existing blog
        await axios.put(`http://localhost:5000/api/admin/blogs/${editingBlog._id}`, formData, {
          headers: { Authorization: `Bearer ${accessToken}` }
        });
        setSuccess('Blog post updated successfully!');
      } else {
        // Create new blog
        await axios.post('http://localhost:5000/api/admin/blogs', formData, {
          headers: { Authorization: `Bearer ${accessToken}` }
        });
        setSuccess('Blog post created successfully!');
      }
      
      closeModal();
      fetchBlogs();
    } catch (err) {
      console.error('Error saving blog:', err);
      setError(err.response?.data?.message || 'Failed to save blog post. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Are you sure you want to delete this blog post? This action cannot be undone.')) return;
    
    try {
      setLoading(true);
      await axios.delete(`http://localhost:5000/api/admin/blogs/${id}`, {
        headers: { Authorization: `Bearer ${accessToken}` }
      });
      setSuccess('Blog post deleted successfully!');
      fetchBlogs();
    } catch (err) {
      console.error('Error deleting blog:', err);
      setError('Failed to delete blog post. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleTogglePublished = async (id, currentStatus) => {
    try {
      setLoading(true);
      await axios.patch(`http://localhost:5000/api/admin/blogs/${id}/publish`, 
        { published: !currentStatus },
        { headers: { Authorization: `Bearer ${accessToken}` }}
      );
      setSuccess(`Blog post ${currentStatus ? 'unpublished' : 'published'} successfully!`);
      fetchBlogs();
    } catch (err) {
      console.error('Error updating blog publish status:', err);
      setError('Failed to update publish status. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleToggleFeatured = async (id, currentStatus) => {
    try {
      setLoading(true);
      await axios.patch(`http://localhost:5000/api/admin/blogs/${id}/feature`, 
        { featured: !currentStatus },
        { headers: { Authorization: `Bearer ${accessToken}` }}
      );
      setSuccess(`Blog post ${currentStatus ? 'removed from' : 'added to'} featured successfully!`);
      fetchBlogs();
    } catch (err) {
      console.error('Error updating blog featured status:', err);
      setError('Failed to update featured status. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  if (loading && blogs.length === 0) {
    return (
      <div className={styles.loadingContainer}>
        <div className={styles.loader}></div>
        <p>Loading blog posts...</p>
      </div>
    );
  }

  return (
    <div>
      <div className={styles.cardHeader}>
        <h1>Blog Management</h1>
        <button className={styles.button} onClick={openAddModal}>
          <FaPlus /> Add New Blog Post
        </button>
      </div>
      
      {error && <div className={styles.errorMessage}>{error}</div>}
      {success && <div className={styles.successMessage}>{success}</div>}
      
      <div className={styles.card}>
        <div className={styles.cardHeader}>
          <h2>Blog Filters</h2>
        </div>
        <div className={styles.cardBody}>
          <div className={styles.filters}>
            <form onSubmit={handleSearch} className={styles.searchForm}>
              <div className={styles.searchInputContainer}>
                <input
                  type="text"
                  placeholder="Search by title or content..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className={styles.searchInput}
                />
                <button type="submit" className={styles.button}>
                  <FaSearch /> Search
                </button>
              </div>
            </form>
            
            <div className={styles.filterControls}>
              <select
                name="category"
                value={filters.category}
                onChange={handleFilterChange}
                className={styles.formControl}
              >
                <option value="">All Categories</option>
                {categories.map(category => (
                  <option key={category} value={category}>{category}</option>
                ))}
              </select>
              
              <select
                name="published"
                value={filters.published}
                onChange={handleFilterChange}
                className={styles.formControl}
              >
                <option value="">All Status</option>
                <option value="true">Published</option>
                <option value="false">Draft</option>
              </select>
              
              <select
                name="featured"
                value={filters.featured}
                onChange={handleFilterChange}
                className={styles.formControl}
              >
                <option value="">All Posts</option>
                <option value="true">Featured</option>
                <option value="false">Not Featured</option>
              </select>
              
              <button 
                onClick={resetFilters} 
                className={`${styles.button} ${styles.buttonSecondary}`}
              >
                Reset Filters
              </button>
            </div>
          </div>
        </div>
      </div>
      
      <div className={styles.card}>
        <div className={styles.cardHeader}>
          <h2>Blog Posts List</h2>
        </div>
        <div className={styles.cardBody}>
          {blogs.length === 0 ? (
            <div className={styles.emptyState}>
              <p>No blog posts found. Create your first blog post!</p>
            </div>
          ) : (
            <table className={styles.table}>
              <thead>
                <tr>
                  <th>Title</th>
                  <th>Category</th>
                  <th>Date</th>
                  <th>Status</th>
                  <th>Featured</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {blogs.map((blog) => (
                  <tr key={blog._id}>
                    <td>{blog.title}</td>
                    <td>{blog.category}</td>
                    <td>{new Date(blog.createdAt).toLocaleDateString()}</td>
                    <td>
                      <span className={blog.published ? styles.statusActive : styles.statusInactive}>
                        {blog.published ? 'Published' : 'Draft'}
                      </span>
                    </td>
                    <td>
                      <span className={blog.featured ? styles.statusActive : styles.statusInactive}>
                        {blog.featured ? 'Featured' : 'Not Featured'}
                      </span>
                    </td>
                    <td>
                      <div className={styles.tableActions}>
                        <button 
                          onClick={() => openEditModal(blog)} 
                          className={`${styles.button} ${styles.buttonSecondary}`}
                          title="Edit Blog Post"
                        >
                          <FaEdit />
                        </button>
                        
                        <button 
                          onClick={() => handleTogglePublished(blog._id, blog.published)}
                          className={`${styles.button} ${blog.published ? styles.buttonSecondary : styles.button}`}
                          title={blog.published ? 'Unpublish' : 'Publish'}
                        >
                          {blog.published ? <FaEyeSlash /> : <FaEye />}
                        </button>
                        
                        <button 
                          onClick={() => handleToggleFeatured(blog._id, blog.featured)}
                          className={`${styles.button} ${blog.featured ? styles.buttonSecondary : styles.button}`}
                          title={blog.featured ? 'Unfeature' : 'Feature'}
                        >
                          {blog.featured ? 'Unfeature' : 'Feature'}
                        </button>
                        
                        <button 
                          onClick={() => handleDelete(blog._id)} 
                          className={`${styles.button} ${styles.buttonDanger}`}
                          title="Delete Blog Post"
                        >
                          <FaTrash />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
          
          {totalPages > 1 && (
            <div className={styles.pagination}>
              <button
                onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                disabled={currentPage === 1}
                className={styles.paginationButton}
              >
                Previous
              </button>
              
              {[...Array(totalPages).keys()].map(page => (
                <button
                  key={page + 1}
                  onClick={() => setCurrentPage(page + 1)}
                  className={`${styles.paginationButton} ${currentPage === page + 1 ? styles.active : ''}`}
                >
                  {page + 1}
                </button>
              ))}
              
              <button
                onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                disabled={currentPage === totalPages}
                className={styles.paginationButton}
              >
                Next
              </button>
            </div>
          )}
        </div>
      </div>
      
      {isModalOpen && (
        <div className={styles.modalOverlay}>
          <div className={styles.modal}>
            <div className={styles.modalHeader}>
              <h2>{editingBlog ? 'Edit Blog Post' : 'Add New Blog Post'}</h2>
              <button onClick={closeModal} className={styles.closeButton}>×</button>
            </div>
            
            <form onSubmit={handleSubmit} className={styles.modalBody}>
              <div className={styles.formGroup}>
                <label htmlFor="title">Title*</label>
                <input
                  type="text"
                  id="title"
                  name="title"
                  value={formData.title}
                  onChange={handleInputChange}
                  className={styles.formControl}
                  required
                />
              </div>
              
              <div className={styles.formGroup}>
                <label htmlFor="summary">Summary</label>
                <textarea
                  id="summary"
                  name="summary"
                  value={formData.summary}
                  onChange={handleInputChange}
                  className={styles.formControl}
                  placeholder="Brief summary of the blog post"
                  rows="2"
                />
              </div>
              
              <div className={styles.formGroup}>
                <label htmlFor="content">Content*</label>
                <textarea
                  id="content"
                  name="content"
                  value={formData.content}
                  onChange={handleInputChange}
                  className={styles.formControl}
                  placeholder="Enter blog content"
                  rows="10"
                  required
                />
              </div>
              
              <div className={styles.formRow}>
                <div className={styles.formGroup}>
                  <label htmlFor="category">Category*</label>
                  <select
                    id="category"
                    name="category"
                    value={formData.category}
                    onChange={handleInputChange}
                    className={styles.formControl}
                    required
                  >
                    <option value="">Select Category</option>
                    {categories.map(category => (
                      <option key={category} value={category}>{category}</option>
                    ))}
                  </select>
                </div>
                
                <div className={styles.formGroup}>
                  <label htmlFor="image">Featured Image URL</label>
                  <input
                    type="url"
                    id="image"
                    name="image"
                    value={formData.image}
                    onChange={handleInputChange}
                    className={styles.formControl}
                    placeholder="https://example.com/image.jpg"
                  />
                </div>
              </div>
              
              <div className={styles.formGroup}>
                <label htmlFor="tags">Tags</label>
                <div className={styles.tagInputContainer}>
                  <input
                    type="text"
                    id="tags"
                    value={tagInput}
                    onChange={handleTagInputChange}
                    onKeyDown={handleTagInputKeyDown}
                    className={styles.formControl}
                    placeholder="Add tags (press Enter or comma to add)"
                  />
                  <button 
                    type="button" 
                    onClick={addTag}
                    className={`${styles.button} ${styles.buttonSecondary}`}
                  >
                    Add
                  </button>
                </div>
                
                <div className={styles.tagsList}>
                  {formData.tags.map(tag => (
                    <span key={tag} className={styles.tag}>
                      {tag}
                      <button 
                        type="button" 
                        onClick={() => removeTag(tag)}
                        className={styles.removeTagButton}
                      >
                        ×
                      </button>
                    </span>
                  ))}
                </div>
              </div>
              
              <div className={styles.formRow}>
                <div className={styles.formGroup}>
                  <label className={styles.checkboxLabel}>
                    <input
                      type="checkbox"
                      name="published"
                      checked={formData.published}
                      onChange={handleInputChange}
                    />
                    Published
                  </label>
                </div>
                
                <div className={styles.formGroup}>
                  <label className={styles.checkboxLabel}>
                    <input
                      type="checkbox"
                      name="featured"
                      checked={formData.featured}
                      onChange={handleInputChange}
                    />
                    Featured Post
                  </label>
                </div>
              </div>
              
              <div className={styles.modalFooter}>
                <button type="button" onClick={closeModal} className={`${styles.button} ${styles.buttonSecondary}`}>
                  Cancel
                </button>
                <button type="submit" className={styles.button} disabled={loading}>
                  {loading ? 'Saving...' : (editingBlog ? 'Update Post' : 'Create Post')}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default BlogManagement;
